kql.query:
let failing =
    union SigninLogs, AADNonInteractiveUserSignInLogs, AADServicePrincipalSignInLogs
    | where TimeGenerated > ago(1d)
    | where ResultType == "50013"
    | summarize Fails = count(), IPs = make_set(IPAddress, 10) by AppId, AppDisplayName;
let working =
    union SigninLogs, AADNonInteractiveUserSignInLogs, AADServicePrincipalSignInLogs
    | where TimeGenerated > ago(14d)
    | where ResultType == "0"
    | distinct AppId;
failing
| join kind=leftanti working on AppId
| sort by Fails desc

let recent =
    union SigninLogs, AADNonInteractiveUserSignInLogs, AADServicePrincipalSignInLogs
    | where TimeGenerated > ago(1d)
    | where ResultType == "90014"
    | summarize Rows = count(), FirstSeen = min(TimeGenerated) by AppId, AppDisplayName;
let before =
    union SigninLogs, AADNonInteractiveUserSignInLogs, AADServicePrincipalSignInLogs
    | where TimeGenerated between (ago(15d) .. ago(1d))
    | where ResultType == "90014"
    | distinct AppId;
recent
| join kind=leftanti before on AppId
| sort by Rows desc

